package at.hausgarten.service;

import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Real graph/files use cases over a transactional owner_state port; no productive browser or DB. */
public final class BrowserMediaRepositoryRulesTests {
    private static int checks;
    private static void yes(boolean value){checks++;if(!value)throw new AssertionError("Browser media repository check "+checks);}
    interface Task {void run()throws Exception;}
    private static void refused(String code,Task task)throws Exception {try{task.run();}catch(IOException expected){yes(expected.getMessage().equals("BROWSER_MEDIA_"+code));return;}throw new AssertionError("Expected BROWSER_MEDIA_"+code);}
    static final class Memory implements BrowserMediaRepositoryRules.Store {
        TreeMap<String,String> values=new TreeMap<>();JSONObject identity=new JSONObject();boolean failReceipt;
        Memory()throws Exception {identity.put("installationId","qa_browser_installation").put("restoreEpoch","qa_browser_epoch_1");}
        public JSONObject identity()throws Exception{return new JSONObject(identity.toString());}
        public String get(String key,String fallback){return values.getOrDefault(key,fallback);}
        public void put(String key,String value)throws Exception {if(failReceipt&&key.startsWith(BrowserMediaRepositoryRules.PREFIX+"request:"))throw new IOException("qa_interrupted_receipt");values.put(key,value);}
        public void remove(String key){values.remove(key);}
        public JSONArray entries(String prefix)throws Exception {JSONArray rows=new JSONArray();for(Map.Entry<String,String> entry:values.entrySet())if(entry.getKey().startsWith(prefix))rows.put(new JSONObject().put("key",entry.getKey()).put("value",new JSONObject(entry.getValue())));return rows;}
        public JSONObject transaction(BrowserMediaRepositoryRules.Work work)throws Exception {TreeMap<String,String> before=new TreeMap<>(values);try{return work.run();}catch(Exception failure){values=before;throw failure;}}
        String fingerprint()throws Exception{return PixelMcpWriteTools.hash(new JSONObject(values));}
    }
    private static JSONObject upload(BrowserMediaFiles files,String id,int seed)throws Exception {byte[] bytes=new byte[65536+seed];new Random(seed).nextBytes(bytes);String request=PixelMcpWriteTools.hash("qa_media_upload_"+id);files.begin(request,bytes.length,"image/jpeg");for(int offset=0;offset<bytes.length;offset+=BrowserMediaFiles.CHUNK_BYTES)files.append(request,offset,Arrays.copyOfRange(bytes,offset,Math.min(bytes.length,offset+BrowserMediaFiles.CHUNK_BYTES)));return files.complete(request);}
    private static JSONObject graph(JSONObject ref,String label)throws Exception {return new JSONObject().put("image",new JSONObject(ref.toString())).put("name",label).put("autoShow",true).put("savedAt","2027-05-18T10:00:00Z");}
    private static JSONObject selected(JSONObject review,String source,String key)throws Exception {JSONArray rows=review.getJSONArray("candidates");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getString("source").equals(source)&&row.getString("key").equals(key))return new JSONObject().put("source",source).put("key",key).put("record_id",row.getString("record_id")).put("record_hash",row.getString("record_hash"));}throw new AssertionError("QA candidate missing");}
    public static void main(String[] ignored)throws Exception {
        SyntheticBusinessData.verify();File root=Files.createTempDirectory("qa_browser_media_repository_").toFile(),media=new File(root,"files/browser-media");try{
            BrowserMediaFiles files=new BrowserMediaFiles(media,new File(root,"uploads"));Memory memory=new Memory();BrowserMediaRepositoryRules rules=new BrowserMediaRepositoryRules(memory,media);yes(!rules.status().getBoolean("mirror_complete")&&memory.values.isEmpty());refused("MIRROR_REQUIRED",()->rules.readRecord("selected"));refused("MIRROR_REQUIRED",rules::inspectCaptured);
            JSONObject first=upload(files,"first",1),second=upload(files,"second",2),firstGraph=graph(first,"QA first"),secondGraph=graph(second,"QA second");JSONArray photos=new JSONArray();for(int i=0;i<25;i++)photos.put(graph(upload(files,"many_"+i,100+i),"QA photo "+i));JSONObject draft=new JSONObject().put("photos",photos).put("customerId","qa_customer");String begin="qa_browser_begin_active";JSONObject started=rules.beginMirror(begin,"active");yes(!started.getBoolean("already_complete")&&rules.beginMirror(begin,"active").getBoolean("replayed"));rules.writeMirrorRecord("qa_browser_stage_selected","active","selected",firstGraph);rules.writeMirrorRecord("qa_browser_stage_draft","active","customer-draft:qa_customer",draft);refused("MIRROR_INCOMPLETE",()->rules.completeMirror("qa_browser_incomplete","active",new JSONArray().put("selected")));yes(!rules.status().getBoolean("mirror_complete"));rules.completeMirror("qa_browser_complete_active","active",new JSONArray().put("selected").put("customer-draft:qa_customer"));yes(rules.status().getString("mode").equals("ACTIVE")&&rules.readRecord("selected").getJSONObject("record").getString("name").equals("QA first"));yes(rules.completeMirror("qa_browser_complete_active","active",new JSONArray().put("selected").put("customer-draft:qa_customer")).getBoolean("replayed"));yes(rules.beginMirror("qa_browser_old_idb_start","active").getBoolean("already_complete"));refused("MIRROR_CLOSED",()->rules.writeMirrorRecord("qa_browser_old_idb_write","active","selected",secondGraph));
            JSONObject current=rules.readRecord("selected");rules.assertReadableReference(current.getString("record_id"),first);checks++;refused("REFERENCE_NOT_ACTIVE",()->rules.assertReadableReference(current.getString("record_id"),second));refused("KEY_INVALID",()->rules.readRecord("customer-draft:"));refused("WRITE_CONFLICT",()->rules.writeRecord("qa_browser_stale","selected","a".repeat(64),secondGraph));JSONObject changed=rules.writeRecord("qa_browser_write","selected",current.getString("record_hash"),secondGraph);yes(rules.writeRecord("qa_browser_write","selected",current.getString("record_hash"),secondGraph).getBoolean("replayed"));refused("REPLAY_MISMATCH",()->rules.writeRecord("qa_browser_write","selected",current.getString("record_hash"),firstGraph));refused("REFERENCE_NOT_ACTIVE",()->rules.assertReadableReference(current.getString("record_id"),first));
            String before=memory.fingerprint();memory.failReceipt=true;try{rules.writeRecord("qa_browser_receipt_abort","selected",changed.getString("record_hash"),firstGraph);throw new AssertionError("Expected QA interrupted receipt");}catch(IOException expected){yes(expected.getMessage().equals("qa_interrupted_receipt"));}memory.failReceipt=false;yes(before.equals(memory.fingerprint()));rules.writeRecord("qa_browser_delete","selected",changed.getString("record_hash"),null);yes(rules.readRecord("selected").isNull("record"));JSONObject captured=rules.inspectCaptured();yes(captured.getInt("blob_count")==27&&captured.getInt("reference_count")>=27&&captured.getInt("record_count")>=4);String oldFile=first.getString("sha256")+".blob";byte[] original=Files.readAllBytes(new File(media,oldFile).toPath());byte[] corrupted=original.clone();corrupted[0]^=1;Files.write(new File(media,oldFile).toPath(),corrupted);refused("ORIGINAL_MISSING_OR_CHANGED",rules::inspectCaptured);Files.write(new File(media,oldFile).toPath(),original);yes(rules.inspectCaptured().getBoolean("mirror_complete"));
            memory.identity.put("restoreEpoch","qa_browser_epoch_2");refused("CONTEXT_CHANGED",rules::status);BrowserMediaRepositoryRules restored=new BrowserMediaRepositoryRules(memory,media);refused("CONTEXT_CHANGED",restored::status);restored.installRestored("qa_browser_restore");yes(restored.status().getString("mode").equals("RESTORE_REVIEW")&&!restored.status().getBoolean("mirror_complete"));refused("RESTORE_REVIEW_REQUIRED",()->restored.readRecord("selected"));refused("MIRROR_REQUIRED",restored::inspectCaptured);refused("MIRROR_NOT_ALLOWED",()->restored.beginMirror("qa_browser_bad_active_mirror","active"));restored.beginMirror("qa_browser_device_begin","device");JSONObject deviceGraph=graph(second,"QA device preserved");restored.writeMirrorRecord("qa_browser_device_record","device","selected",deviceGraph);restored.completeMirror("qa_browser_device_complete","device",new JSONArray().put("selected"));yes(restored.inspectCaptured().getString("mode").equals("RESTORE_REVIEW"));JSONObject review=restored.reviewCandidates();yes(review.getBoolean("required")&&review.getJSONArray("candidates").length()==3);JSONArray selection=new JSONArray().put(selected(review,"device","selected")).put(selected(review,"backup","customer-draft:qa_customer"));refused("DUPLICATE_KEY",()->restored.prepareRestoreSelection("qa_browser_duplicate_selection",review.getString("record_hash"),new JSONArray().put(selected(review,"device","selected")).put(selected(review,"backup","selected"))));refused("WRITE_CONFLICT",()->restored.prepareRestoreSelection("qa_browser_stale_selection","f".repeat(64),selection));JSONObject prepared=restored.prepareRestoreSelection("qa_browser_prepare",review.getString("record_hash"),selection);String selectionHash=prepared.getString("selection_hash"),selectedBefore=memory.fingerprint();yes(restored.verifyPreparedRestoreSelection("qa_browser_prepare",review.getString("record_hash"),selection,selectionHash).getBoolean("valid")&&selectedBefore.equals(memory.fingerprint()));refused("WRITE_CONFLICT",()->restored.verifyPreparedRestoreSelection("qa_browser_wrong_prepare",review.getString("record_hash"),selection,selectionHash));memory.failReceipt=true;try{restored.activateSelection("qa_browser_activate_interrupted",selectionHash);throw new AssertionError("Expected QA interrupted activation");}catch(IOException expected){yes(expected.getMessage().equals("qa_interrupted_receipt"));}memory.failReceipt=false;yes(selectedBefore.equals(memory.fingerprint())&&restored.status().getString("mode").equals("RESTORE_REVIEW"));restored.activateSelection("qa_browser_activate",selectionHash);yes(restored.readRecord("selected").getJSONObject("record").getString("name").equals("QA device preserved")&&restored.readRecord("customer-draft:qa_customer").getJSONObject("record").getJSONArray("photos").length()==25);yes(restored.activateSelection("qa_browser_activate",selectionHash).getBoolean("replayed"));yes(restored.activateSelection("qa_browser_activate_new_retry",selectionHash).getBoolean("already_active"));yes(restored.verifyPreparedRestoreSelection("qa_browser_prepare",review.getString("record_hash"),selection,selectionHash).getBoolean("valid"));JSONObject active=restored.readRecord("selected");restored.writeRecord("qa_browser_later_user_edit","selected",active.getString("record_hash"),firstGraph);yes(restored.inspectCaptured().getBoolean("mirror_complete"));refused("CONTEXT_CHANGED",()->restored.writeRecord("qa_browser_delete","selected",changed.getString("record_hash"),null));
            JSONObject invalid=new JSONObject().put("image","data:image/jpeg;base64,qa_inline_forbidden");refused("INLINE_MEDIA_FORBIDDEN",()->restored.writeRecord("qa_browser_inline_invalid","selected",restored.readRecord("selected").getString("record_hash"),invalid));JSONObject forged=new JSONObject(first.toString()).put("byte_size",first.getLong("byte_size")+1);refused("ORIGINAL_MISSING_OR_CHANGED",()->restored.writeRecord("qa_browser_size_invalid","selected",restored.readRecord("selected").getString("record_hash"),graph(forged,"QA wrong length")));
            System.out.println("PASS "+checks+" browser-media graph/25photos/CAS/replay/transaction rollback/immutable historical files/restore source separation/explicit selection/epoch/byte-integrity checks;synthetic host port,no Android IDB proof");
        }finally{try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){for(Path path:(Iterable<Path>)paths.sorted(Comparator.reverseOrder())::iterator)Files.deleteIfExists(path);}}
    }
}
